ex_err_int_overflow.src:
// 錯誤教案 #1：整數溢位
// BUG：int 只能表示到 2147483647（INT_MAX），13! = 6227020800 超出範圍，溢位後數字變成怪值。
// 學生常見想法：「階乘就是一直乘，結果一定是正的」。
// 修正：改用 long long（或 unsigned long long，但 unsigned 不會變負，仍會繞回）。
#include <iostream>

int factorial(int n) {
    int result = 1;
    for (int i = 2; i <= n; i++) {
        result = result * i;   // 溢位發生在這一行
    }
    return result;
}

int main() {
    std::cout << "10! = " << factorial(10) << std::endl;   // 正確：3628800
    std::cout << "13! = " << factorial(13) << std::endl;   // 錯誤：應為 6227020800，實際溢位
    return 0;
}

ex_err_array_oob.src:
// 錯誤教案 #2：陣列越界（寫到相鄰的欄位）
// BUG：data 只有 4 格（索引 0~3），迴圈卻寫到 i <= 4，data[4] 實際落在 guard 上，guard 被蓋掉。
// 學生常見想法：「for (i = 0; i <= n) 才會跑完 n+1 次」。
// 修正：把條件改成 i < 4，或改用 std::array 並用 .size() 當邊界。
// 註：struct 內的成員記憶體連續排列，data[4] 必定與 guard 重疊（同一編譯器下可重現）。
#include <iostream>

struct Block {
    int data[4];
    int guard;     // 本來應該永遠是 42
};

int main() {
    Block b;
    b.guard = 42;
    for (int i = 0; i <= 4; i++) {   // BUG：應為 i < 4
        b.data[i] = i * 10;          // i == 4 時寫進 guard
    }
    std::cout << "guard = " << b.guard << "（應為 42）" << std::endl;
    return 0;
}

ex_err_null_deref.src:
// 錯誤教案 #5：空指標解參考（走訪鏈結串列時超過最後一個節點）
// BUG：迴圈內同時讀 cur->next->val，但最後一個節點的 next 是 nullptr，
//      解參考 nullptr 在原生 Linux 會 SIGSEGV 崩潰。
// 註：本專案的 wasm 引擎不會崩潰，而是讀到位址 0x00000000 的值（0）。這是環境差異，
//     右側欄要說明，不改寫程式來追求崩潰。
// 學生常見想法：「while (cur) 跑完就結束，印 next 的值沒問題」。
// 修正：只在 cur->next != nullptr 時才讀 cur->next->val。
#include <iostream>

struct Node {
    int val;
    Node* next;
};

int main() {
    Node b{20, nullptr};
    Node a{10, &b};
    Node* cur = &a;
    while (cur != nullptr) {
        // BUG：最後一輪 cur->next 是 nullptr，cur->next->val 解參考空指標
        std::cout << "值：" << cur->val << "，下一個值：" << cur->next->val << std::endl;
        cur = cur->next;
    }
    return 0;
}

